package gen

// Loaders are the scripts `ezc codegen shell|mise|direnv` print: each loads the environment `ezc env export` gives,
// and opens with comments that say how to use it. They hold no value, so they need no repo and can be committed.
// How a user loads the environment is theirs to choose; these are starting points.
var Loaders = map[string]string{
	"shell": `# Load the environment from ezc into a shell. Generated by ` + "`ezc codegen shell`" + `.
#
# Use it in one of these ways:
#   in ~/.zshrc, ~/.bashrc or a script:  eval "$(ezc codegen shell)"
#   as a file:                           ezc codegen shell -o load-env.sh, then . ./load-env.sh
#
# It loads the repo of the working directory as it runs (the store alone outside a repo);
# EZC_ENV picks the environment. It never fails the shell: ` + "`ezc env`" + ` says what is wrong.
` + loaderBody,

	"mise": `# Load this repo's environment from ezc in mise. Generated by ` + "`ezc codegen mise`" + `.
#
# Save it in the repo, commit it, and point mise.toml at it:
#   ezc codegen mise -o .ezc/env.sh
#
#   [env]
#   _.source = ".ezc/env.sh"
#
# It never fails mise: a broken config must not make ` + "`cd`" + ` unusable. ` + "`ezc env`" + ` is the check
# that fails, so make tasks depend on it.
` + loaderBody,

	"direnv": `# Load this repo's environment from ezc in direnv. Generated by ` + "`ezc codegen direnv`" + `.
#
# Save it as the repo's .envrc (or add these lines to the one it has), then allow it:
#   ezc codegen direnv -o .envrc
#   direnv allow
#
# It never fails direnv: ` + "`ezc env`" + ` says what is wrong.
` + loaderBody,
}

// loaderBody is every loader's code. Never drop its guard: see the comment it carries.
const loaderBody = `#
# EZC_SHIM_LOADING marks the ezc this runs: an ezc that mise installed is a mise shim, which
# loads the repo's environment before it runs ezc. Without the mark that never ends.
if [ -z "${EZC_SHIM_LOADING:-}" ] && command -v ezc >/dev/null 2>&1; then
  eval "$(EZC_SHIM_LOADING=1 ezc env export 2>/dev/null || true)"
fi
`
